package dev.zomboidmelee.boxing;
/** Collision-limited visual corner lean. Never changes velocity, player position or aiming rotation. */
public final class Lean30 {
 static Object left,right,owner,world;static long sampled;static double target,targetForward;static final Bodycam27.Spring BLEND=new Bodycam27.Spring(),FORWARD=new Bodycam27.Spring();
 static void register(Object event){left=R.make("net.minecraft.client.KeyMapping","key.zomboid_global_melee.lean_left",90,"key.categories.movement");right=R.make("net.minecraft.client.KeyMapping","key.zomboid_global_melee.lean_right",88,"key.categories.movement");R.call(event,"register",left);R.call(event,"register",right);}
 static boolean down(Object key){return key!=null&&R.yes(R.call(key,"isDown"));}
 static boolean option(Object m,String name){try{return down(R.get(R.get(m,"options"),name));}catch(IllegalStateException missing){return false;}}
 static int choose(boolean center,boolean l,boolean r,int request){if(request!=0)return request<0&&l?-1:request>0&&r?1:0;if(!center)return l&&!r?-1:r&&!l?1:0;return 0;}
 static boolean clear(Object p,Object level,double ax,double ay,double az,double bx,double by,double bz){Object a=R.make("net.minecraft.world.phys.Vec3",ax,ay,az),b=R.make("net.minecraft.world.phys.Vec3",bx,by,bz);Object ctx=R.make("net.minecraft.world.level.ClipContext",a,b,R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"COLLIDER"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),p);return "MISS".equals(R.call(R.call(level,"clip",ctx),"getType").toString());}
 static double eye(Object p){return R.coord(p,"Y")+R.num(R.call(p,"getEyeHeight"));}
 static boolean canOffset(Object p,Object level,double side){double yaw=Math.toRadians(R.num(R.call(p,"getYRot"))),x=R.coord(p,"X"),y=eye(p),z=R.coord(p,"Z"),dx=Math.cos(yaw)*side,dz=Math.sin(yaw)*side;for(double height:new double[]{-.08,.08})for(double edge:new double[]{-.08,.08})if(!clear(p,level,x+edge,y+height,z,x+dx+edge,y+height,z+dz))return false;return true;}
 static boolean ahead(Object p,Object level,double side){double yaw=Math.toRadians(R.num(R.call(p,"getYRot"))),x=R.coord(p,"X")+Math.cos(yaw)*side,y=eye(p),z=R.coord(p,"Z")+Math.sin(yaw)*side;return clear(p,level,x,y,z,x-Math.sin(yaw)*.85,y,z+Math.cos(yaw)*.85);}
 static void tick(Object m,Object p,Object level){if(p!=owner||level!=world){owner=p;world=level;target=0;sampled=BoxingClient16.CLOCK.getAsLong();BLEND.clear();FORWARD.clear();}target=targetForward=0;if(p==null||R.get(m,"screen")!=null||!Move25.allowed(p)||Parkour20.active(p)||Slide28.lowVisual(p))return;double yaw=Math.toRadians(R.num(R.call(p,"getYRot"))),side=Bodycam26.dx*Math.cos(yaw)+Bodycam26.dz*Math.sin(yaw);target=Math.max(-.60,Math.min(.60,side*2.8));targetForward=Math.max(-1,Math.min(1,(-Bodycam26.dx*Math.sin(yaw)+Bodycam26.dz*Math.cos(yaw))*6));int request=down(left)==down(right)?0:down(left)?-1:1;try{boolean l=canOffset(p,level,-.28)&&ahead(p,level,-.28),r=canOffset(p,level,.28)&&ahead(p,level,.28);int edge=choose(ahead(p,level,0),l,r,request);if(edge!=0&&(request!=0||Math.abs(target)<.05||Math.signum(target)==edge))target=edge;if(!canOffset(p,level,target*.28))target=0;}catch(IllegalStateException unavailable){target=0;}}
 static double amount(){long now=BoxingClient16.CLOCK.getAsLong();double dt=(now-sampled)/1e9;if(dt>=.004){sampled=now;if(dt>.25){BLEND.clear();FORWARD.clear();}else{BLEND.step(target,dt,2.7);FORWARD.step(targetForward,dt,2.7);}}return Math.max(-1,Math.min(1,BLEND.value));}
 public static void camera(Object camera){Object m=BoxingClient16.mc(),p=R.get(m,"player");if(p!=owner||p==null||R.get(m,"screen")!=null||!Action19.firstPerson(m))return;try{if(R.call(camera,"getEntity")!=p)return;}catch(IllegalStateException unavailable){return;}double w=amount();if(Math.abs(w)<.001)return;double shift=w*.28;try{if(!canOffset(p,world,shift))return;Object pos=R.call(camera,"getPosition");double yaw=Math.toRadians(R.num(R.call(p,"getYRot")));R.call(camera,"setPosition",R.num(R.get(pos,"x"))+Math.cos(yaw)*shift,R.num(R.get(pos,"y"))-.018*Math.abs(w),R.num(R.get(pos,"z"))+Math.sin(yaw)*shift);}catch(IllegalStateException unavailable){}}
 public static void angles(Object event){Object m=BoxingClient16.mc();if(R.get(m,"player")!=owner||owner==null||R.get(m,"screen")!=null||!Action19.firstPerson(m))return;R.call(event,"setRoll",(float)(R.num(R.call(event,"getRoll"))+amount()*10));R.call(event,"setPitch",(float)(R.num(R.call(event,"getPitch"))+FORWARD.value*1.3));}
}
